INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63850493', 63850493, 'analyze_legacy', 'Kab. Pekalongan', 'kabkota', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'Penyusunan AHSP Tahun 2027', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Pekalongan (Kab.)', 90000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Penyusunan Biaya Penerapan SMKK Penyusunan dokumen AHSP bidang Kebinamargaan. Penyusunan dokumen AHSP bidang SDA. Penyusunan dokumen AHSP bidang Keciptakaryaan. Aplikasi Database', 'Dalam pekerjaan perencanaan seperti yang dimaksud pada KAK ini, Konsultan Perencana harus memperlihatkan persyaratan-persyaratan serta ketentuan-ketentuan antara lain persyaratan umum pekerjaan, fungsional dan prosedural, sebagaimana uraian berikut: i. Persyaratan Umum Pekerjaan, yaitu setiap bagian dari pekerjaan Penyusunan AHSP harus dilaksanakan secara benar dan tuntas sampai dengan dihasilkannya produk yang telah ditetapkan dan diterima dengan baik oleh Pejabat Pembuat Komitment (PPK) ii. Persyaratan Fungsional, yaitu pekerjaan Penyusunan AHSP harus dilaksanakan dengan profesionalisme dan tanggung jawab yang tinggi sebagai Konsultan Perencana iii. Persyaratan Prosedural, dimana penyelesaian administrasi sehubungan dengan pelaksanaan tugas/pekerjaan harus dilaksanakan sesuai dengan prosedur dan peraturan-peraturan yang berlaku. iv. Kriteria lain, selain kriteria umum diatas, untuk pekerjaan penyusunan AHSP berlaku pula ketentuan-ketentuan seperti standar, pedoman peraturan yang berlaku antara lain: a. Ketentuan yang diberlakukan untuk pekerjaan Kegiatan yang bersangkutan, yaitu Surat Perjanjian Pekerjaan, dan ketentuan – ketentuan lain sebagai dasar perjanjiannya. b. Tata Cara Penyusunan AHSP dilaksanakan dengan merujuk dasar Surat Edaran Direktur Jenderal Bina Konstruksi Nomor 182/SE/Dk/2025 tentang Tata Cara Penyusunan Perkiraan Biaya Pekerjaan Konstruksi Bidang Pekerjaan Umum.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 190820);
