INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62092872', 62092872, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM32 KANTOR IMIGRASI KELAS II TPI TAREMPA', 'Pengadaan Tenaga Alih Daya Penjaga Keamanan pada Kantor Imigrasi Kelas II TPI Tarempa - Kepulauan Riau Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Kepulauan Riau, Kepulauan Anambas (Kab.)', 241410000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '39 OB', 'Pengadaan tenaga alih daya (outsourcing) penjaga keamanan mencakup tugas pokok menjaga keamanan, ketertiban, dan aset di area yang ditentukan, serta melaksanakan prosedur tanggap darurat dan pelaporan', 'Tugas Pokok (4P) 1) Pengaturan: Mengatur alur masuk/keluar orang & kendaraan, pemeriksaan identitas (KTP/SIM), penertiban parkir, dan pengelolaan tamu. 2) Penjagaan: Berjaga di pos, mengawasi area kerja, memastikan pintu/gerbang tertutup, dan memelihara aset perusahaan. 3) Pengawalan: Mengawal objek/orang penting di lingkungan kerja. 4) Patroli: Melakukan patroli rutin (berkala) untuk memastikan keamanan dan ketertiban lingkungan Tugas Tambahan & Pendukung 1) Pelayanan & Informasi: Memberikan informasi dasar, membantu tamu menemukan lokasi, bersikap ramah dan profesional. 2) Pengawasan: Memantau lingkungan dengan patroli dan melaporkan situasi via HT serta membuat laporan harian. 3) Penanganan Insiden: Menangani keadaan darurat, kecelakaan, atau insiden lain dan membuat laporan. 4) Pemeliharaan Aset: Menjaga dan memelihara inventaris serta aset perusahaan. 5) Preventif & Kuratif: Melaksanakan pemeliharaan rutin (preventif) dan perbaikan (kuratif) sarana keamanan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 192131);
