INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62092212', 62092212, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Sewa Peralatan Pendukung Kebersihan Pada Kantor Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 16080000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12.0 Paket', 'Pekerjaan ini meliputi penyediaan jasa sewa perlengkapan dan peralatan pendukung kebersihan untuk menunjang kebersihan, kerapian, dan kenyamanan lingkungan kerja pada Kantor Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Layanan diselenggarakan secara berkesinambungan selama masa kontrak sesuai kebutuhan operasional perkantoran. Ruang lingkup pekerjaan mencakup penyediaan peralatan utama kebersihan yang digunakan secara langsung dalam kegiatan pembersihan, serta peralatan pendukung kebersihan yang berfungsi menunjang efektivitas dan kelancaran pelaksanaan kebersihan gedung dan ruang kerja. Seluruh peralatan yang disewakan harus dalam kondisi baik, layak pakai, dan siap digunakan.', 'Jenis layanan meliputi penyewaan peralatan utama kebersihan yang digunakan langsung dalam proses pembersihan serta peralatan pendukung kebersihan sebagai pelengkap operasional. Seluruh peralatan yang disediakan harus berfungsi dengan baik, layak pakai, dan memenuhi standar kebersihan serta keselamatan kerja. Cakupan layanan mencakup penyediaan peralatan sesuai kebutuhan kantor, pengantaran dan penarikan peralatan, pemeliharaan rutin, serta perbaikan atau penggantian peralatan apabila terjadi kerusakan selama masa sewa tanpa biaya tambahan. Peralatan harus tersedia dan siap digunakan setiap saat guna mendukung kegiatan kebersihan harian. Penyedia wajib menjamin kontinuitas layanan sewa dan ketersediaan peralatan secara berkelanjutan selama masa kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 192848);
