INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62054961', 62054961, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN TEGAL PARANG - JAKSEL', '7.01.04.6.01.0001 Penyediaan Spanduk Musrenbang Kelurahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 689472, 'January 2026', 'APBD', 1, 1, '1 Paket', '1. Tahap Persiapan : a. Bertanggung jawab terhadap pelaksanaan survei hasil Rembuk RW yang dilakukan oleh tim pendamping Rembuk RW; b. Menetapkan tim penyelenggara Sidang Kelompok Kelurahan dengan tugas - tugas sebagai berikut : - Mengumpulkan jadwal, agenda dan tempat Musrenbang Kelurahan minimal 7 (tujuh) hari sebelum kegiatan dilakukan; - Menyiapkan kesiapan jaringan internet, proyektor, layar, tempat peralatan dan bahan/materi serta kelengkapan lain yang dibutuhkan dalam pelaksanaan Musrenbang Kelurahan; dan - Mengundang peserta mengikuti kegiatan Musrenbang Kelurahan di Aula Kantor Kelurahan Tegal Parang. c. Memastikan usulan hasil Rembuk RW yang akan dibahas pada Musrenbang Kelurahan telah di input kedalam Sistem Informasi Perencanaan. 2. Tahap Pelaksanaan : a. Membuka acara Musrenbang Kelurahan; b. Membahas hasil Rembuk RW dengan metode sebagai berikut : - Membahas usulan hasil Rembuk RW dari masing-masing RW yang diusulkan ke kelurahan; - Dalam pembahasan, tidak diperkenankan untuk mengubah usulan hasil Rembuk RW (menambah kegiatan baru, merubah nomenklatur, lokasi, volume, anggaran); dan - Melakukan penyelarasan hasil Rembuk RW dengan Arah Kebijakan Pembangunan Kelurahan serta program dan kegiatan prioritas kelurahan. c. Menyepakati hasil pembahasan sebagaimana dimaksud di atas dengan para peserta; d. Mencetak dokumen hasil pembahasan Musrenbang Kelurahan secara langsung dari Sistem Informasi Perencanaan; e. Menandatangani Berita Acara pelaksanaan Musrenbang Kelurahan; f. Menutup pelaksanaan Musrenbang Kelurahan; dan g. Menyampaikan hasil Musrenbang Kelurahan kepada RW. 3. Tahap Pelaporan : a. Berita Acara Kesepakatan; b. Daftar Usulan Kegiatan Prioritas; c. Daftar Usulan yang di Teruskan; d. Daftar Inventaris Aset; e. Tabel Verifikasi Usulan Fisik Tim Teknis; f. Foto Pelaksanaan Musrenbang Kelurahan; g. Surat Tugas Tim Pendamping Rembuk RW dari Kelurahan; h. Surat Tim Penyelenggara Kegiatan Musrenbang Kelurahan; i. Paparan Lurah pada Musrenbang Kelurahan; j. Laporan Rembuk RW dan Musrenbang Kelurahan.', 'Spesifikasi yang diperlukan untuk penyediaan spanduk, snack dan makan minum rapat Rembuk RW dan Musrenbang Kelurahan sesuai ketentuan melalui e-Order. Penyediaan Spanduk Kegiatan Musrenkel atau Musrenkec', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 193356);
