INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102398', 62102398, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perpanjangan Lisensi Mobile Device dan Asset Management (SOTI) Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 8000000000, 'May 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan perpanjangan lisensi dan layanan pengelolaan (Managed Service) untuk sistem Mobile Device Management (MDM) guna mengamankan aset perangkat (Laptop/Mobile) yang tersebar di Kantor Imigrasi (Kanim). Pekerjaan ini bertujuan memastikan keberlanjutan fungsi pelacakan lokasi, penguncian jarak jauh, dan manajemen aplikasi dari kontrak sebelumnya yang berakhir November 2025, serta menyediakan tenaga ahli on-site untuk dukungan operasional harian.', '1. Fitur Aplikasi MDM (SOTI): > Pemantauan terpusat (Dashboard) untuk multi-OS (Windows, iOS, Linux, Android). > Fitur Grouping berdasarkan lokasi Kantor Imigrasi. > Pelacakan lokasi aktual (Real-time) dan riwayat lokasi (History). > Fitur File Transfer, Send Script, dan Blacklist Aplikasi. > Remote Control berbasis HTML5 atau Desktop Application > Manajemen Pengguna (User Management) berjenjang sesuai hirarki. 2. Implementasi: > Jasa Deployment (On-Premise atau On-Cloud) pada server Imigrasi. > Jasa Enrollment, Konfigurasi Profil, Rules, dan 1x Pelatihan. 3. Managed Service (SDM & Support) selama 1 Tahun: > 1 Orang Programmer On-Site: S1 Teknik Informatika, pengalaman 2 Tahun. > 1 Orang Programmer Standby: S1 Teknik Informatika, pengalaman 2 Tahun. > Engineer On-Site: 5 hari kerja (07.30 - 14.00 WIB) di Data Center Ditjen Imigrasi. > Engineer Standby: Bersifat On-Call sesuai kebutuhan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 194504);
