INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102403', 62102403, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perpanjangan Lisensi Application Performance Monitoring kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 8500000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan perpanjangan lisensi dan layanan platform Application Performance Monitoring (APM) berbasis Artificial Intelligence (AI) untuk menjamin performa dan ketersediaan layanan SIMKIM. Lingkup pekerjaan meliputi penyediaan lisensi platform Dynatrace untuk pemantauan infrastruktur (hybrid/multicloud) dan manajemen performa aplikasi (microservices), dukungan teknis untuk transisi dari manajemen reaktif ke prediktif, serta peningkatan observabilitas sistem guna mempercepat resolusi masalah (Mean Time To Repair).', '1. Platform: Dynatrace (Sesuai standarisasi eksisting Tahun 2024). 2. Modul Utama: > Infrastructure Monitoring: Kemampuan memantau full-stack (On-Prem, Hybrid, Multicloud) secara real-time. > Application Performance Management (APM): Penelusuran distribusi penuh (full distributed tracing) untuk aplikasi dan microservices. 3. Fitur Cerdas: > Analisis berbasis AI (Artificial Intelligence) untuk deteksi masalah otomatis. > Manajemen Prediktif (mendeteksi potensi gangguan sebelum terjadi). > Skrip respons otomatis untuk mengurangi biaya operasional. 4. Tujuan Teknis: Meningkatkan Mean Time To Repair (MTTR) dan memberikan visibilitas end-to-end terhadap kesehatan sistem SIMKIM.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 194779);
