INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102404', 62102404, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perpanjangan Lisensi Cloud Web Mail Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 10000000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1.0 Thn', 'Menyediakan layanan sewa perangkat lunak aplikasi manajemen internal berbasis Cloud Webmail yang terintegrasi (SaaS) untuk mendukung produktivitas dan kolaborasi 7.500 pegawai. Lingkup pekerjaan mencakup penyediaan akun email bisnis dengan domain instansi (@imigrasi.go.id), aplikasi produktivitas (Docs, Sheets, Slides), penyimpanan data berbasis cloud, layanan konferensi video, serta fitur keamanan siber tingkat lanjut dan dukungan teknis dengan SLA tinggi.', '1. Kapasitas User: Lisensi untuk 7.500 pegawai/pengguna; 2. Fitur Email: Email bisnis aman (@imigrasi.go.id), jaminan reputasi SMTP (anti-blokir/spam), dan SLA pengiriman email OTP maks. 30 detik; 3. Kolaborasi & Video: Rapat video hingga 500 peserta dengan fitur rekaman >12 jam; terintegrasi dengan Docs, Sheets, Slides, Drive, dan Calendar; 4. Penyimpanan: Kapasitas gabungan (pooled storage) sebesar 1 TB per pengguna; 5. Keamanan: Fitur otomatisasi blokir sumber tak dikenal, antispam, antivirus, dan manajemen perangkat (endpoint management); 6. Ketersediaan (Availability): Jaminan No Planned Downtime (Layanan terus menerus tanpa henti); 7. Manajemen & Support: Tersedia dashboard admin untuk monitoring/utilisasi dan dukungan teknis penuh untuk isu pengiriman email global.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 194871);
