INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62101818', 62101818, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Sewa Perangkat Printer Paspor Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 20370600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1.0 Thn', 'Melanjutkan sewa perangkat printer paspor untuk Tahun 2026 guna mendukung pelayanan penerbitan paspor di seluruh Unit Pelaksana Teknis (UPT) Keimigrasian. Lingkup pekerjaan meliputi: 1. Penyediaan 300 unit printer paspor yang kompatibel dan terintegrasi dengan SIMKIM. 2. Instalasi dan konfigurasi perangkat di lokasi yang ditentukan. 3. Penyediaan SDK/API terbuka (open public) untuk personalisasi chip dan integrasi sistem. 4. Layanan pemeliharaan dan penggantian suku cadang (full maintenance) selama masa sewa. 5. Jaminan layanan purna jual (Service Level Agreement) berupa penggantian unit rusak maksimal 3 (tiga) hari kerja sejak pelaporan. 6. Jaminan ketersediaan suku cadang dari prinsipal minimal 10 Tahun.', '1. Teknologi Cetak: 4-color thermal inkjet (Dye C,M,Y + Pigment K) dengan resolusi hingga 4800 dpi. 2. Kecepatan: Mode standar maks. 9 detik, High Quality maks. 26 detik. 3. Fitur Paspor (MRTD): Kompatibel ICAO 9303, dilengkapi RFID Reader/Encoder (ISO 14443, USB CCID, SAM Slot). 4. Kamera & Keamanan: Kamera 2 MP CMOS untuk verifikasi, serta fitur pengamanan biometrik sidik jari untuk operasional alat. 5. Ketahanan: Print head durability hingga 50.000 buku; kapasitas cartridge hingga 8.000 buku. 6. Integrasi: Mendukung Windows 7 & 10, menyediakan API & DLL, serta koneksi USB 2.0. 7. Fisik & Daya: Konsumsi daya rendah (approx 32W), noise level standar ISO, dan memiliki stasiun pembersih (cleaning station) yang mudah dirawat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 195611);
