INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102400', 62102400, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perpanjangan Lisensi SSL Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 45000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Pkt', 'Melakukan perpanjangan lisensi keamanan digital (SSL/TLS) untuk domain *.imigrasi.go.id guna menjamin keamanan pertukaran data pada layanan publik berbasis web milik Direktorat Jenderal Imigrasi. Lingkup pekerjaan meliputi penyediaan lisensi sertifikat tipe Wildcard validasi organisasi selama 1 (satu) Tahun, penyediaan akses manajemen sertifikat (dashboard), serta layanan purna jual berupa bantuan aktivasi, instalasi, dan pemecahan masalah (troubleshooting) teknis.', '1. Produk: Lisensi TLS/SSL Certificate (Brand: Digicert, sesuai standarisasi eksisting); 2. Tipe Sertifikat: Wildcard SSL (melindungi domain utama dan seluruh subdomain); 3. Durasi: Masa aktif 1 (satu) Tahun (berakhir Mei 2026); 4. Fitur: Enkripsi standar industri (SHA-256, 2048-bit RSA), kompatibilitas browser 99.9%; 5. Fasilitas Manajemen: Akses penuh ke portal Cert Central Dashboard untuk pengelolaan sertifikat; 6. Layanan Dukungan: Pendampingan penerbitan (issuance), instalasi, dan dukungan teknis (troubleshooting) jika terjadi kendala pada browser atau server selama masa berlangganan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 196239);
