INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102396', 62102396, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perpanjangan Lisensi Security dan Monitoring kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 21500000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1.0 Thn', 'Melakukan perpanjangan lisensi solusi keamanan siber (Security) dan pemantauan sistem (Monitoring) secara komprehensif untuk melindungi integritas data dan keberlangsungan operasional organisasi. Lingkup pekerjaan mencakup pembaruan hak akses penggunaan perangkat lunak, penyediaan akses terhadap basis data intelijen ancaman (Threat Intelligence) terbaru, fitur deteksi dan mitigasi serangan (Malware, Ransomware, Phishing, DDoS), serta penyediaan dukungan teknis resmi dari prinsipal untuk pemeliharaan sistem.', '1. Fitur Deteksi & Proteksi: Kemampuan analisis trafik jaringan dan log sistem untuk mendeteksi pola mencurigakan serta memitigasi serangan siber (Malware, Ransomware, Phishing, DDoS); 2. Threat Intelligence: Akses pembaruan otomatis database ancaman global terkini untuk antisipasi serangan baru (Zero-day attack); 3. Monitoring & Visibilitas: Penyediaan dashboard terpusat dan pelaporan real-time untuk memantau status keamanan, kepatuhan (compliance), dan performa sistem secara menyeluruh; 4. Manajemen Akses: Fitur perlindungan aset digital dan infrastruktur dari akses yang tidak sah (Unauthorized Access); 5. Dukungan Teknis: Layanan support dan maintenance dari vendor/prinsipal selama masa berlaku lisensi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 196295);
