INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102394', 62102394, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Sewa Perangkat Layanan Keimigrasian Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30700000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1.0 Pkt', 'Menyediakan layanan sewa perangkat keras pendukung operasional layanan keimigrasian untuk Unit Pelaksana Teknis (UPT) di seluruh Indonesia. Lingkup pekerjaan mencakup penyediaan unit, distribusi ke lokasi, instalasi, serta layanan purna jual (perbaikan/penggantian unit) selama masa sewa untuk total 2.929 unit perangkat yang terdiri dari PC All-in-One, UPS, MRTD Reader, Passport Laminator, dan Thermal Printer.', 'PC All-in-One (1.254 Unit): - Proc: Min. Intel Core i7-11700 (8 Core). - RAM/Storage: 16 GB DDR4 / 1TB SSD. - Layar: Min. 21". - Fitur Khusus: Kustomisasi BIOS logo Ditjen Imigrasi, Wajib ber-TKDN (PDN). UPS (419 Unit): - Kapasitas: 650VA/390W. - Backup Time: >= 30 Menit. - Wajib ber-TKDN (PDN). MRTD Reader (593 Unit): - Kemampuan: Baca dokumen Visible, IR, UV, ePassport (RFID) chip read/write. - Resolusi: Up to 550 dpi. - Durability: IP54 rated. - Passport Laminator (328 Unit): - Speed: 0 - 770 mm/min. - Temp: 0 - 160 °C. Thermal Printer (335 Unit): - Speed: Up to 8 ips. - Fitur: Auto resolution (203/300 dpi), external roll bracket. - Wajib ber-TKDN (PDN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 196317);
