INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102397', 62102397, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Sewa Cloud Data Center II Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 17600000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1.0 Pkt', 'Menyediakan layanan Sewa Cloud Data Center (Infrastruktur sebagai Layanan / IaaS) untuk melanjutkan program strategis Direktorat Teknologi Informasi Keimigrasian dalam memigrasikan sebagian besar aplikasi dan basis data pelayanan keimigrasian ke lingkungan cloud. Lingkup pekerjaan meliputi penyediaan komputasi (virtual core/RAM), penyimpanan (storage), jaringan, dan keamanan siber yang fleksibel (scalable), serta layanan manajemen operasional (managed services) untuk menjamin ketersediaan layanan (availability) yang tinggi.', '1. Layanan IaaS: Penyediaan Virtual Machine (Compute), Block/Object Storage dengan performa tinggi (SSD/NVMe), dan Load Balancer. 2. Lokasi & Kepatuhan: Pusat Data harus berlokasi di wilayah hukum Indonesia (Data Sovereignty) dan memiliki sertifikasi standar internasional (ISO 27001, PCI-DSS, dan Tier III/IV Facility). 3.Konektivitas: Jaminan bandwidth internet dan interkoneksi lokal (IIX/OpenIXP) yang memadai serta latensi rendah. 4. Keamanan: Dilengkapi fitur Native Security seperti Cloud Firewall, WAF (Web Application Firewall), dan proteksi Anti-DDoS. 5. Keandalan (SLA): Jaminan Service Level Agreement (SLA) Uptime minimal 99,5%