INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102371', 62102371, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Sewa Jaringan Komunikasi Sistem Keimigrasian Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 51437496000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, Pkt, @ 51437496000 )', 'Menyediakan layanan Sewa Jaringan Komunikasi Sistem Keimigrasian yang komprehensif untuk TA 2024. Pekerjaan mencakup penyediaan konektivitas data dedicated (IP VPN) dan internet dedicated untuk Direktorat Jenderal Imigrasi dan Satuan Kerja (Satker) terkait, layanan Managed Service untuk perangkat pendukung, keamanan jaringan (Managed Firewall), serta penyediaan infrastruktur backbone berteknologi MPLS dengan redundansi tinggi. Penyedia juga wajib melakukan instalasi, pemeliharaan proaktif, penyediaan jalur alternatif (dual topology), integrasi sistem, serta alih pengetahuan (transfer knowledge) kepada pengguna.', '1. Layanan Konektivitas: Penyediaan Jaringan Komunikasi Data Dedicated (IP VPN) dan Internet Dedicated untuk Ditjen Imigrasi, Pusat Data, dan Satker sesuai tabel lokasi; 2. Infrastruktur Jaringan: Menggunakan MPLS Backbone domestik full redundant (konfigurasi Ring dengan auto self-healing); 3. Cakupan Wilayah: Jaringan backbone Fiber Optic mencakup minimal 2/3 (dua pertiga) wilayah Indonesia; 4. Redundansi & Keandalan: Menyediakan 2 (dua) topologi jaringan berbeda (Core Network, POP, Last Mile) untuk failover otomatis; 5. Managed Services: Termasuk instalasi, konfigurasi, dukungan kesisteman proaktif, Managed Firewall, dan Managed Access Point; 6. Fleksibilitas Bandwidth: Mendukung peningkatan bandwidth pada waktu kritis (bursting) sesuai kebutuhan; 7. Dukungan & Integrasi: Koordinasi pemecahan masalah (troubleshooting) dan integrasi jaringan dengan instansi lain; 8. Pelatihan & Pelaporan: Melakukan Transfer Knowledge (minimal 2 kali untuk 10 orang) terkait NMS/MRTG dan konfigurasi, serta menyampaikan laporan berkala (Pendahuluan, Bulanan, Akhir, dan Utilisasi).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 196463);
