INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102522', 62102522, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Perangkat Autogate Kegiatan Pengadaan Perangkat Pengolah Data dan Komunikasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 25000000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '( 10, Unit, @ 2500000000 )', 'Pengadaan perangkat autogate (gerbang otomatis) untuk meningkatkan efisiensi, kecepatan, dan akurasi proses pemeriksaan keimigrasian bagi penumpang internasional di Tempat Pemeriksaan Imigrasi (TPI)', 'Pengadaan autogate dengan spesifikasi teknis minimal sebagai berikut: Pintu otomatis harus terdiri dari entry dan exit yang bekerja otomatis jika ada orang di dalam mantrap area; Terdapat device untuk membaca travel document (paspor) baik untuk WNI maupun WNA; Sistem harus mampu membaca dan melakukan autentikasi e-passport; Memiliki kamera untuk mengambil data biometrik (wajah) yang mampu menyesuaikan dengan tinggi badan penumpang; Mampu mengirimkan data MRZ dan foto wajah secara realtime ke server Imigrasi; Mampu memberikan feedback ke penumpang apakah statusnya clear atau harus diproses di meja counter imigrasi; Memiliki kemampuan untuk mendeteksi liveness (kehadiran nyata) dari penumpang, bukan foto/image; Memiliki interaktif display untuk melakukan arahan kepada penumpang tentang urutan proses; Autogate harus memiliki sensor Anti Tailgating yang mampu mencegah penumpang menerobos masuk lebih dari satu orang ke dalam mantrap; Autogate so