INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62101819', 62101819, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Kegiatan Pemeliharaan Infrastruktur SIMKIM Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 5000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Thn', 'Melaksanakan jasa pemeliharaan infrastruktur perangkat keras (hardware) Sistem Informasi Manajemen Keimigrasian (SIMKIM) secara menyeluruh guna menjamin ketersediaan (availability) dan keandalan layanan publik. Lingkup pekerjaan mencakup pelaksanaan Preventive Maintenance (pencegahan), Corrective Maintenance (perbaikan/penggantian komponen), Monitoring & Performance Tuning 24/7, serta pengelolaan Backup & Disaster Recovery untuk server, storage, dan perangkat jaringan.', '1. Preventive Maintenance: Pemeriksaan fisik, pengecekan kesehatan komponen (HDD/SSD, RAM, PSU), pembaruan firmware/BIOS, dan uji failover cluster untuk memastikan High Availability. 2. Corrective Maintenance: Penanganan insiden kerusakan perangkat (hardware failure), penggantian komponen (hot swap), pemulihan sistem pasca-gangguan (recovery), dan re-konfigurasi. 3. Monitoring & Tuning: Pemantauan performa 24/7 menggunakan NMS (seperti PRTG/SolarWinds/Zabbix), optimasi penggunaan sumber daya (CPU/RAM/Bandwidth) untuk mencegah bottleneck, dan penyusunan capacity planning. 4. Backup & Disaster Recovery: Pengelolaan backup berkala (harian/mingguan/bulanan) ke tape library/offsite, serta pelaksanaan simulasi Disaster Recovery Plan (DRP). 5. Target: Menghindari downtime layanan dan menjaga integritas data keimigrasian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 197148);
