INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62101822', 62101822, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Sewa Perangkat Kesisteman Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 14806134000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1.0 Thn', 'Melanjutkan pelaksanaan Sewa Perangkat Kesisteman (di bawah Kontrak Payung) untuk mendukung operasional layanan keimigrasian di seluruh UPT Indonesia. Lingkup pekerjaan meliputi penyediaan sewa perangkat, pemeliharaan, dan jaminan purna jual untuk perangkat-perangkat fotografi, biometrik, komputasi, dan pencetakan dokumen, antara lain: - 700 Unit Kamera DSLR (Canon R50). - 143 Unit Fingerprint Scanner (Biomorf). - 66 Unit Laptop High-End (MacBook Pro M3). - 52 Unit Laptop Standard (MacBook Air M3). - 700 Unit Printer Multifungsi (Epson L5290). - 130 Unit Webcam 4K (Insta360). - 700 Unit Aksesoris Daya (Dummy Battery).', '1. Kamera DSLR: Resolusi 24.2 MP, DIGIC X Processor, 4K Movie, Dual Pixel CMOS AF II (Ref: Canon R50). 2. Biometric Scanner: Tenprint scanner (4 plain fingers, 2 thumbs), Sertifikasi FBI IAFIS IQS CJSI-RS-0010 & ANSI/NIST-ITL-1-2000 (Ref: Biomorf B-Scan 1051). 3. Laptop Tipe 1: Processor M3 Pro/Max (11-Core CPU, 14-Core GPU), RAM 18GB, SSD 512GB (Ref: MacBook Pro 14"). 4. Laptop Tipe 2: Processor M3 (8-Core CPU, 8-Core GPU), RAM 8GB, SSD 256GB (Ref: MacBook Air 13.6"). 5. Printer: Inkjet Tank, Print/Scan/Copy/Fax, Max Res 5760x1440 dpi, Speed up to 33 ppm (Ref: Epson L5290). 6. Webcam: Resolusi 4K, AI Tracking, Gesture Control, Sensor 1/2" (Ref: Insta360 Link 2). 7. Power Kit: Dummy Battery LP-E17 dengan AC Adapter untuk daya kontinu (Indoor).', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 197167);
