INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102372', 62102372, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Managed Service Security and Network Operating Center Kegiatan Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 20409500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1.0 Pkt', 'Melaksanakan pekerjaan Managed Services Security and Network Operational Center untuk melindungi infrastruktur vital dan data pada Sistem Informasi Manajemen Keimigrasian (SIMKIM). Pekerjaan mencakup penyediaan Platform Operasi Keamanan Siber terintegrasi berbasis AI/Machine Learning, layanan monitoring keamanan (SOC) dan jaringan (NOC) 24/7, penerapan Threat Intelligence untuk mendeteksi ancaman global dan aktor negara (state-sponsored actors), integrasi sistem SIEM, SOAR, dan XDR, pelaksanaan Vulnerability Assessment & Penetration Testing (VAPT), serta penyediaan tenaga ahli on-site, pelatihan keamanan siber, dan pelaporan insiden secara real-time.', '1. Platform & Teknologi: Penyediaan platform keamanan dengan kapabilitas AI/ML yang teruji mengamankan >300 juta pengguna dan tingkat negara; 2. Layanan SOC 24/7: Monitoring real-time terhadap Malware, Ransomware, DDoS, Phishing, dan Insider Threats; 3. Threat Intelligence: Akses ke intelijen ancaman global, deteksi zero-day, pemantauan dark web, dan analisis aktor serangan (hacker groups); 4. Integrasi Sistem: Implementasi SIEM (analisis log otomatis), SOAR (otomasi respon), dan XDR (deteksi endpoint/cloud/server) termasuk pembuatan Playbook; 5. Pengujian Keamanan (VAPT): Scanning berkala, malware testing, dan simulasi serangan (penetration test) untuk menutup celah keamanan; 6. Layanan NOC: Pemantauan performa jaringan (bandwidth, latensi, packet loss) 24/7; 7. SDM & Dukungan: Penyediaan On-Site Engineer di Ditjen Imigrasi dan dukungan prioritas saat insiden; 8. Transfer Knowledge: Pelatihan teknis untuk Direktorat TIK dan Security Awareness untuk pegawai; 9. Pelaporan & Log: Dokumentasi lengkap (laporan insiden, VAPT, mitigasi) dan penyimpanan log/syslog sesuai kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 197348);
