INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102360', 62102360, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Pemeliharaan Perangkat Autogate Kegiatan Pemeliharaan Perangkat Keras pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 52694000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan pemeliharaan korektif dan dukungan operasional sistem Autogate (Pintu Perlintasan Elektronik) di Tempat Pemeriksaan Imigrasi (TPI) Udara dan Laut. Lingkup pekerjaan mencakup penjaminan fungsi hardware (pemindai paspor, sidik jari, kamera) dan software (Visionbox Orchestra Platform), penyediaan dukungan jarak jauh (remote support) oleh teknisi prinsipal, analisis kerentanan keamanan, serta pemulihan layanan (recovery) sesuai SLA yang ketat. Penyedia juga wajib melakukan alih pengetahuan kepada petugas imigrasi dan menyediakan layanan teknis operasional setiap hari (Senin-Minggu, 01.00-24.00 WIB).', '1. Objek Pemeliharaan: Perangkat Autogate (Hardware & Software Visionbox Orchestra) yang terpasang di TPI Bandara dan Laut. 2. Lingkup Layanan: - Korektif: Perbaikan fisik dan sistem saat terjadi kegagalan. - Support Principal: Remote support Tahunan langsung dari teknisi prinsipal untuk analisis ancaman/risiko. - Testing: Pengujian komponen fungsional dan koneksi ke Sistem Imigrasi Pusat (Cekal/Masa Berlaku). 3. Waktu Layanan: Senin s.d Minggu (termasuk hari libur), pukul 01.00 s.d 24.00 WIB. 4. SLA & Respon: Penanganan pemulihan layanan gagal dan identifikasi masalah proaktif. 5. Pelaporan: Laporan kejadian kerusakan, rekapitulasi penggantian suku cadang, perhitungan SLA, dan denda (jika ada). 6. Transfer Knowledge: Pelatihan penanganan level pertama untuk petugas Imigrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 197434);
