INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102395', 62102395, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Sewa Cloud Data Center I Kegiatan Pengelolaan Data dan Informasi pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 24000000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1.0 Pkt', 'Menyediakan layanan Sewa Cloud Data Center I berbasis teknologi AWS (Amazon Web Services) sebagai infrastruktur utama Sistem Informasi Manajemen Keimigrasian (SIMKIM). Pekerjaan mencakup penyediaan resource cloud yang high availability dan aman, layanan pengelolaan penuh (Managed Services) 24/7, jasa profesional untuk konfigurasi (provisioning) dan pemutakhiran sistem, serta pelaksanaan uji coba backup/recovery dan transfer pengetahuan (knowledge transfer) kepada petugas teknis.', '1. Platform Cloud: Penyediaan infrastruktur Cloud AWS dan pendukungnya yang fleksibel, skalabel, dan tahan terhadap serangan siber. 2. Managed Services (24/7): > Monitoring menyeluruh (Infrastructure, App Uptime, Resource Workload). > Penyediaan Unified Dashboard dan Log Aggregation. > Analisis Database (Query Analytics & Performance). > Manajemen Biaya (Cost Monitoring & Optimization). > Pemeliharaan (Preventive & Corrective Maintenance) dan Troubleshooting. > Pelaporan Bulanan. 3. Layanan Profesional: Konfigurasi server (provisioning), pemutakhiran infrastruktur sesuai regulasi, dan optimalisasi kinerja. 4. Operasional Keamanan: Uji coba mekanisme backup, restore, dan recovery secara berkala. 5. Pengembangan SDM: Pelaksanaan Transfer Knowledge operasional cloud kepada tim teknis internal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 197784);
